INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web) VALUES (29, 8, 'Darwin build: Objective-C bridge outside luv''s read-only source', 'work', 'done', NULL, '2026-10-14, flake.nix, docs/luv-wishlist.md: on aarch64-darwin luv loads from a writable copy (package $out/share/luv pruned to build/ bridge dylib and objective-c/ as luv''s applicationPackage does; dev shell ${XDG_CACHE_HOME:-~/.cache}/luv-in-space/luv-<shortRev>; check $TMPDIR/luv). Linux derivations byte-identical (same drv paths); nix flake check --no-build --all-systems passes; nix build and scripts/test pass. Darwin build untested: no Apple Silicon machine (decision 6: Target platforms).', 'Part of `plan 8: walking skeleton`. `task 22: Flake: luv input, dev shell, package and nix run opening an empty window` builds the game against luv''s sources straight from the flake input (`${luv}/` on `CL_SOURCE_REGISTRY` in `flake.nix`). On `aarch64-darwin`, luv''s `objective-c/exception-bridge.lisp` compiles a dylib to `<luv source>/../build/objective-c-exception-bridge-<stamp>.dylib`, i.e. into the read-only Nix store path, so `nix build` and loading `luv-in-space` in the dev shell will fail there. luv''s own `applicationPackage` avoids this by copying its tree into `$out/share/luv` and keeping `build/` and `objective-c/` on Darwin.

## Do
- In `flake.nix`, on Darwin only (`lib.optionalString pkgs.stdenv.hostPlatform.isDarwin`): copy `${luv}` into a writable directory (package: `$out/share/luv`, kept with its `build/` and `objective-c/` as luv''s recipe does; dev shell: a cache directory, e.g. `${XDG_CACHE_HOME:-$HOME/.cache}/luv-in-space/luv-<rev>`) and put that on `CL_SOURCE_REGISTRY` instead of `${luv}/`.
- Keep Linux unchanged.
- Verify with `nix flake check --no-build --all-systems`; a real build needs an Apple Silicon machine (`decision 6: Target platforms`: Darwin is evaluated only), so note it as untested if none is available.
- The wishlist entry already exists in `docs/luv-wishlist.md` (Objective-C bridge output directory).', '2026-10-14T17:08:42Z', '2026-10-14T17:28:42Z', 22, 0);
INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web) VALUES (30, 8, 'Live shader pipelines for the scene', 'work', 'done', NULL, '2026-10-14, src/scene.lisp, src/shaders.lisp, src/main.lisp, AGENTS.md, docs/luv-capabilities.md', 'Part of `plan 8: walking skeleton`, follow-up of `task 26: Live image dev loop for luv-in-space`: shader redefinitions while playing in `./sly` should show on the next frame.

