INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web) VALUES (38, 10, 'Design: the game in one page and the ship(s)', 'work', 'done', NULL, '2026-10-14, docs/design.md (new: intro, The game in one page, The ship(s); other sections PLACEHOLDER(39..43)); decisions 22-27; follow-ups task 44, task 45', 'First part of `plan 10: game design`: create `docs/design.md` and write its sections "The game in one page" and "The ship(s)", as the plan body specifies.

## Read first
