INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web) VALUES (39, 10, 'Design: flight controls, control modes, views, instruments and time warp', 'work', 'done', NULL, '2026-10-14, docs/design.md (Flight: controls, control modes, views, instruments, time warp); decisions 29, 30, 31', 'Second part of `plan 10: game design`: write the first half of the section "Flight" in `docs/design.md`: controls, control modes, views, instruments, time warp, as the plan body specifies.

