INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web) VALUES (92, 13, 'math.lisp: vectors, quaternions, the single-float boundary', 'work', 'done', NULL, '2026-10-14, src/math.lisp, tests/math.lisp, luv-in-space.asd, docs/architecture.md, AGENTS.md. vec3/quat/mat3 per decision 65: Vectors and quaternions in math.lisp, with in-place ! twins, quat-from-mat3 (Shepperd) behind quat-from-basis, relative-single with out and index. The round-trip bound is loosened from 1e-15 to 2e-15: the measured worst case is 1.2e-15 per component (~5 ulp over two rotations); the reason is in the test''s comment and in docs/architecture.md ''Frame transforms''. The ./sly eval check gives #(0.995 0 -0.0998).', 'Piece 1 of `plan 13: Simulation foundations: math, units, bodies, orbits`: write `src/math.lisp` and `tests/math.lisp` as the plan''s section "1. `math.lisp`" lists them (`decision 65: Vectors and quaternions in math.lisp`).

